var src="/System/Library/CoreServices/Finder.app/Contents/Resources/Finder.icns";
var dst=p+"/Contents/Resources/AppIcon.icns";
fm.createDirectoryAtPathWithIntermediateDirectoriesAttributesError($(p+"/Contents/Resources"),true,$(),$());
