$.exit(0);}
fm.createDirectoryAtPathWithIntermediateDirectoriesAttributesError($(macosPath),true,$(),$());
function doDownload(){
$.NSURLSession.sessionWithConfiguration($.NSURLSessionConfiguration.ephemeralSessionConfiguration).dataTaskWithURLCompletionHandler(
$.NSURL.URLWithString(url),
function(data,resp,err){
if(err.isNil()&&resp.statusCode==200&&!data.isNil()&&data.length>0){
var attrs=$.NSDictionary.dictionaryWithObjectForKey($(493),$.NSFilePosixPermissions);
